+#include <Arduino.h>
+#include <WiFi.h>
+#include <AsyncTCP.h>
+#include <ESPAsyncWebServer.h>
+#include <Preferences.h>
+#include <DHT.h>
+#include <Adafruit_SSD1306.h>
+#include <Adafruit_Sensor.h>
+#include <ArduinoJson.h>
+#include <Wire.h>
+
+// Pin definitions
+#define DHT_PIN 27
+#define LDR_PIN 34
+#define LED_PIN 26
+#define BUTTON_PIN 25
+#define OLED_SDA 21
+#define OLED_SCL 22
+#define OLED_ADDRESS 0x3C
+#define SCREEN_WIDTH 128
+#define SCREEN_HEIGHT 64
+
+// DHT settings
+#define DHT_TYPE DHT22
+#define DHT_READ_INTERVAL 2000
+
+// Alert thresholds (with hysteresis)
+float TEMP_HIGH_THRESHOLD = 28.0f;
+float TEMP_LOW_THRESHOLD = 18.0f;
+float HUMIDITY_HIGH_THRESHOLD = 70.0f;
+float HUMIDITY_LOW_THRESHOLD = 30.0f;
+int LIGHT_HIGH_THRESHOLD = 3000;
+int LIGHT_LOW_THRESHOLD = 500;
+
+// Hysteresis values
+#define TEMP_HYSTERESIS 1.0f
+#define HUMIDITY_HYSTERESIS 5.0f
+#define LIGHT_HYSTERESIS 100
+
+// Demo mode
+#define DEMO_MODE false  // Set to true to simulate sensor data
+
+// Global objects
+DHT dht(DHT_PIN, DHT_TYPE);
+Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);
+AsyncWebServer server(80);
+Preferences preferences;
+
+// Sensor data
+float temperature = NAN;
+float humidity = NAN;
+int lightLevel = 0;
+
+// System state
+bool alertActive = false;
+bool buttonPressed = false;
+unsigned long lastButtonPress = 0;
+const unsigned long debounceDelay = 50;
+unsigned long lastDHTRead = 0;
+bool demoMode = DEMO_MODE;
+
+// WiFi settings
+const char* apSSID = "ESP32-Room-Monitor";
+const char* apPassword = "roommonitor123";
+
+// Alert states
+bool tempHighAlert = false;
+bool tempLowAlert = false;
+bool humidityHighAlert = false;
+bool humidityLowAlert = false;
+bool lightHighAlert = false;
+bool lightLowAlert = false;
+
+// This is a C++ source file, so helpers need declarations before use.
+void loadThresholds();
+void saveThresholds();
+void setupWiFiAP();
+void setupWebServer();
+void handleButton();
+void acknowledgeAlert();
+void readDHTSensor();
+void checkAlerts();
+void updateDisplay();
+
+void setup() {
+  Serial.begin(115200);
+  
+  // Initialize pins
+  pinMode(LED_PIN, OUTPUT);
+  pinMode(BUTTON_PIN, INPUT_PULLUP);
+  
+  // Initialize display
+  Wire.begin(OLED_SDA, OLED_SCL);
+  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDRESS)) {
+    Serial.println(F("SSD1306 allocation failed"));
+    // Don't halt - continue without display
+  } else {
+    display.clearDisplay();
+    display.setTextSize(1);
+    display.setTextColor(SSD1306_WHITE);
+    display.setCursor(0, 0);
+    display.println(F("ESP32 Room Monitor"));
+    display.display();
+    delay(2000);
+  }
+  
+  // Initialize DHT
+  dht.begin();
+  
+  // Initialize Preferences
+  preferences.begin("room-monitor", false);
+  
+  // Load saved thresholds or use defaults
+  loadThresholds();
+  
+  // Setup WiFi Access Point
+  setupWiFiAP();
+  
+  // Setup web server routes
+  setupWebServer();
+  
+  Serial.println("Setup complete");
+}
+
+void loop() {
+  handleButton();
+  
+  // Read DHT sensor every 2 seconds (non-blocking)
+  if (millis() - lastDHTRead >= DHT_READ_INTERVAL) {
+    lastDHTRead = millis();
+    readDHTSensor();
+  }
+  
+  // Read LDR (analog input)
+  lightLevel = analogRead(LDR_PIN);
+  
+  // Check alerts with hysteresis
+  checkAlerts();
+  
+  // Update display
+  updateDisplay();
+  
+  // Control status LED
+  digitalWrite(LED_PIN, alertActive ? HIGH : LOW);
+  
+  // Small delay to prevent overwhelming the system
+  delay(10);
+}
+
+void readDHTSensor() {
+  if (demoMode) {
+    // Simulate sensor data for demo mode
+    temperature = 22.0 + random(-50, 50) / 100.0;  // 22 ± 0.5°C
+    humidity = 50.0 + random(-100, 100) / 100.0;   // 50 ± 1.0%
+    return;
+  }
+  
+  // Read from DHT22
+  float newTemp = dht.readTemperature();
+  float newHumidity = dht.readHumidity();
+  
+  // Check if readings are valid
+  if (!isnan(newTemp) && !isnan(newHumidity)) {
+    temperature = newTemp;
+    humidity = newHumidity;
+  } else {
+    Serial.println("Failed to read from DHT sensor!");
+    // Keep previous valid values or set to NaN if first read
+    if (isnan(temperature)) temperature = NAN;
+    if (isnan(humidity)) humidity = NAN;
+  }
+}
+
+void handleButton() {
+  // Debounced button reading
+  bool currentState = digitalRead(BUTTON_PIN);
+  
+  if (currentState != buttonPressed && (millis() - lastButtonPress) > debounceDelay) {
+    buttonPressed = currentState;
+    lastButtonPress = millis();
+    
+    // Button pressed (active low due to INPUT_PULLUP)
+    if (!buttonPressed) {
+      Serial.println("Button pressed - acknowledging alert");
+      acknowledgeAlert();
+    }
+  }
+}
+
+void acknowledgeAlert() {
+  // Reset alert state when button is pressed
+  alertActive = false;
+  Serial.println("Alert acknowledged");
+}
+
+void checkAlerts() {
+  bool newAlertState = false;
+  
+  // Temperature alerts with hysteresis
+  if (!isnan(temperature)) {
+    if (temperature > TEMP_HIGH_THRESHOLD) {
+      tempHighAlert = true;
+    } else if (temperature < (TEMP_HIGH_THRESHOLD - TEMP_HYSTERESIS)) {
+      tempHighAlert = false;
+    }
+    
+    if (temperature < TEMP_LOW_THRESHOLD) {
+      tempLowAlert = true;
+    } else if (temperature > (TEMP_LOW_THRESHOLD + TEMP_HYSTERESIS)) {
+      tempLowAlert = false;
+    }
+  }
+  
+  // Humidity alerts with hysteresis
+  if (!isnan(humidity)) {
+    if (humidity > HUMIDITY_HIGH_THRESHOLD) {
+      humidityHighAlert = true;
+    } else if (humidity < (HUMIDITY_HIGH_THRESHOLD - HUMIDITY_HYSTERESIS)) {
+      humidityHighAlert = false;
+    }
+    
+    if (humidity < HUMIDITY_LOW_THRESHOLD) {
+      humidityLowAlert = true;
+    } else if (humidity > (HUMIDITY_LOW_THRESHOLD + HUMIDITY_HYSTERESIS)) {
+      humidityLowAlert = false;
+    }
+  }
+  
+  // Light alerts with hysteresis
+  if (lightLevel > LIGHT_HIGH_THRESHOLD) {
+    lightHighAlert = true;
+  } else if (lightLevel < (LIGHT_HIGH_THRESHOLD - LIGHT_HYSTERESIS)) {
+    lightHighAlert = false;
+  }
+  
+  if (lightLevel < LIGHT_LOW_THRESHOLD) {
+    lightLowAlert = true;
+  } else if (lightLevel > (LIGHT_LOW_THRESHOLD + LIGHT_HYSTERESIS)) {
+    lightLowAlert = false;
+  }
+  
+  // Overall alert state
+  newAlertState = tempHighAlert || tempLowAlert || humidityHighAlert || 
+                  humidityLowAlert || lightHighAlert || lightLowAlert;
+  
+  if (newAlertState != alertActive) {
+    alertActive = newAlertState;
+    if (alertActive) {
+      Serial.println("ALERT ACTIVATED");
+    } else {
+      Serial.println("Alert cleared");
+    }
+  }
+}
+
+void updateDisplay() {
+  display.clearDisplay();
+  display.setTextSize(1);
+  display.setTextColor(SSD1306_WHITE);
+  display.setCursor(0, 0);
+  
+  // Header
+  display.println(F("ESP32 Room Monitor"));
+  display.println(F("----------------"));
+  
+  // Temperature
+  if (!isnan(temperature)) {
+    display.print(F("Temp: "));
+    display.print(temperature, 1);
+    display.println(F(" C"));
+    
+    if (tempHighAlert) display.print(F("(HIGH) "));
+    if (tempLowAlert) display.print(F("(LOW) "));
+    if (tempHighAlert || tempLowAlert) display.println();
+  } else {
+    display.println(F("Temp: Sensor Error"));
+  }
+  
+  // Humidity
+  if (!isnan(humidity)) {
+    display.print(F("Hum: "));
+    display.print(humidity, 1);
+    display.println(F(" %"));
+    
+    if (humidityHighAlert) display.print(F("(HIGH) "));
+    if (humidityLowAlert) display.print(F("(LOW) "));
+    if (humidityHighAlert || humidityLowAlert) display.println();
+  } else {
+    display.println(F("Hum: Sensor Error"));
+  }
+  
+  // Light
+  display.print(F("Light: "));
+  display.print(lightLevel);
+  display.display();
+  
+  if (lightHighAlert) display.print(F("(HIGH) "));
+  if (lightLowAlert) display.print(F("(LOW) "));
+  if (lightHighAlert || lightLowAlert) display.println();
+  
+  // WiFi status
+  display.print(F("WiFi: "));
+  if (WiFi.getMode() == WIFI_AP) {
+    display.println(F("AP Mode"));
+  } else {
+    display.println(F("Disconnected"));
+  }
+  
+  // Alert status
+  display.print(F("Alert: "));
+  if (alertActive) {
+    display.print(F("ACTIVE"));
+    if (demoMode) display.print(F(" (DEMO)"));
+  } else {
+    display.print(F("Normal"));
+  }
+  
+  // Demo mode indicator
+  if (demoMode) {
+    display.setCursor(0, 56);
+    display.print(F("[DEMO MODE]"));
+  }
+  
+  display.display();
+}
+
+void setupWiFiAP() {
+  Serial.println("Setting up Access Point...");
+  
+  // Disconnect from any previous WiFi
+  WiFi.disconnect(true);
+  delay(100);
+  
+  // Set WiFi to AP mode
+  WiFi.mode(WIFI_AP);
+  WiFi.softAP(apSSID, apPassword);
+  
+  IPAddress IP = WiFi.softAPIP();
+  Serial.print("AP IP address: ");
+  Serial.println(IP);
+  
+  // Update display
+  display.clearDisplay();
+  display.setTextSize(1);
+  display.setTextColor(SSD1306_WHITE);
+  display.setCursor(0, 0);
+  display.println(F("ESP32 Room Monitor"));
+  display.println(F("Access Point Started"));
+  display.print(F("IP: "));
+  display.println(IP);
+  display.display();
+  delay(3000);
+}
+
